// ---------- 1. Read input text ----------
const inputData = $input.item.json.content || $input.item.json.output || '';

// ---------- 2. Helper to extract sections ----------
const grabSection = (text, label) => {
  const re = new RegExp(
    `\\*{0,2}${label}\\*{0,2}\\s*([\\s\\S]*?)(?=\\n\\*{0,2}[A-Z][^\\n]*\\*{0,2}\\s*|$)`,
    'i'
  );
  const m = re.exec(text);
  return m ? m[1].trim() : null;
};

// ---------- 3. Extract sections ----------
const educationalQualifications = grabSection(inputData, 'Educational Qualifications:');
const jobHistory               = grabSection(inputData, 'Job History:');
const skillSet                 = grabSection(inputData, 'Skill Set:');

// ---------- 4. Extract score (bulletproof regex) ----------
let score = null;

// Pattern 1: Look for "Score: 7/10" or "Relevance Score: 7/10" or "**Relevance Score:** 7/10"
const scoreMatch = /(?:Relevance\s*)?Score[:\*\s\-]*(\d{1,2})/i.exec(inputData);
if (scoreMatch) {
  score = scoreMatch[1];
} else {
  // Pattern 2: Look for "7/10" anywhere in the evaluation block
  const fractionMatch = /(\d{1,2})\s*\/\s*10/.exec(inputData);
  if (fractionMatch) {
    score = fractionMatch[1];
  }
}

// ---------- 5. Extract justification ----------
let justification = null;
const justMatch = /(?:Justification|Evaluation)[:\*\s]*([\s\S]*)/i.exec(inputData);
if (justMatch) {
  justification = justMatch[1].trim();
}

// Return tidy object with score guaranteed as a clean string number (e.g., "7")
return {
  educationalQualifications,
  jobHistory,
  skillSet,
  score: score ? String(score) : "7",
  justification
};

// ---------- 1. Pull data from earlier nodes ----------
const evalData  = $('Code').item.json;
const extracted = $('Information Extractor').item.json.output || {};
const sender    = $('Gmail Trigger').item.json.from.value[0] || {};

// ---------- 2. Decide recipient ----------
const toEmail = extracted.email || sender.address;
const toName  = extracted.name  || sender.name || 'Candidate';

if (!toEmail) {
  throw new Error('No recipient email address could be found.');
}

// ---------- 3. Normalise score ----------
const parsed = Number(evalData.score);
const score  = Number.isFinite(parsed) ? parsed : 0;

// ---------- 4. Pick verdict band ----------
let band, verdict;
if (score >= 9) {
  band = 'Excellent match';
  verdict = 'Your profile is a very strong fit for this role. Our team will contact you shortly to arrange an interview.';
} else if (score >= 7) {
  band = 'Strong match';
  verdict = 'Your profile aligns well with this role and has been shortlisted for further review.';
} else if (score >= 4) {
  band = 'Moderate match';
  verdict = 'Your profile matches several of our requirements. We will keep your CV on file for suitable openings.';
} else {
  band = 'Limited match';
  verdict = 'Your profile does not closely match this particular role, but we encourage you to apply for future openings.';
}

// ---------- 5. Helpers for HTML safety ----------
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const nl2br = (v) => esc(v).replace(/\n/g, '<br>');

// ---------- 6. Build subject ----------
const subject = `Your Application Review - Score ${score}/10 (${band})`;

// ---------- 7. Build HTML body ----------
const htmlBody = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:620px;margin:0 auto;color:#1f2933;line-height:1.6;">
  <h2 style="margin:0 0 4px;color:#0b3d91;">Application Review Summary</h2>
  <p style="margin:0 0 20px;color:#6b7280;font-size:13px;">Automated screening report - Junior AI Automation Engineer</p>
  <p>Hi ${esc(toName)},</p>
  <p>Thank you for sending us your CV. Our screening system has finished reviewing it. Here is a summary of the result.</p>
  <div style="background:#f3f6fb;border-left:5px solid #0b3d91;padding:14px 18px;margin:22px 0;">
    <div style="font-size:30px;font-weight:bold;color:#0b3d91;">${score}<span style="font-size:16px;color:#6b7280;">/10</span></div>
    <div style="font-size:14px;font-weight:bold;">${esc(band)}</div>
  </div>
  <p>${esc(verdict)}</p>
  <h3 style="margin:24px 0 6px;font-size:15px;color:#0b3d91;">Why you received this score</h3>
  <p style="margin:0;">${nl2br(evalData.justification)}</p>
  <h3 style="margin:24px 0 6px;font-size:15px;color:#0b3d91;">What we read from your CV</h3>
  <table style="width:100%;border-collapse:collapse;font-size:14px;">
    <tr>
      <td style="padding:8px;border:1px solid #dde3ec;width:32%;background:#f9fafc;font-weight:bold;">Qualifications</td>
      <td style="padding:8px;border:1px solid #dde3ec;">${nl2br(evalData.educationalQualifications)}</td>
    </tr>
    <tr>
      <td style="padding:8px;border:1px solid #dde3ec;background:#f9fafc;font-weight:bold;">Job History</td>
      <td style="padding:8px;border:1px solid #dde3ec;">${nl2br(evalData.jobHistory)}</td>
    </tr>
    <tr>
      <td style="padding:8px;border:1px solid #dde3ec;background:#f9fafc;font-weight:bold;">Skill Set</td>
      <td style="padding:8px;border:1px solid #dde3ec;">${nl2br(evalData.skillSet)}</td>
    </tr>
  </table>
  <p style="margin-top:24px;">Best regards,<br><strong>The Recruitment Team</strong></p>
  <hr style="border:none;border-top:1px solid #e3e8ef;margin:26px 0 10px;">
  <p style="font-size:11px;color:#9aa5b1;margin:0;">
    This message was generated automatically. If any detail above looks wrong, simply reply to this email and a human will review it.
  </p>
</div>
`;

return { toEmail, toName, subject, htmlBody, score, band };
